	repoRoot, err := loadConfig()
	if err != nil {
		return nil, SearchOutput{}, fmt.Errorf("failed to load config: %w", err)
	}

	// Use the repo package to search
	repo := repopkg.NewRepo(repoRoot)
	results, err := repo.Search(ctx, input.Query)
	if err != nil {
		return nil, SearchOutput{}, fmt.Errorf("search failed: %w", err)
	}

	// Convert results to our format
	searchResults := make([]SearchResult, len(results))
	for i, result := range results {
		searchResults[i] = SearchResult{
			Path:        result.Path,
			Type:        result.Type,
			Description: result.Description,
		}
	}

	return nil, SearchOutput{Results: searchResults}, nil
}

