func Search(ctx context.Context, req *mcp.CallToolRequest, input SearchInput) (*mcp.CallToolResult, SearchOutput, error) {
	repoRoot, err := loadConfig()
	if err != nil {
		return nil, SearchOutput{}, fmt.Errorf("failed to load config: %w", err)
	}

	// For now, implement a simple file search since the repo package API is not yet defined
	var results []SearchResult

	// Walk the directory and search for files matching the query
	err = filepath.Walk(repoRoot, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}

		if info.IsDir() {
			return nil
		}

		// Simple name-based search for now
		if strings.Contains(strings.ToLower(info.Name()), strings.ToLower(input.Query)) {
			relPath, err := filepath.Rel(repoRoot, path)
			if err != nil {
				return nil
			}
			results = append(results, SearchResult{
				Path:        relPath,
				Type:        "file",
				Description: fmt.Sprintf("File matching query: %s", input.Query),
			})
		}

		return nil
	})

	if err != nil {
		return nil, SearchOutput{}, fmt.Errorf("search failed: %w", err)
	}

	return nil, SearchOutput{Results: results}, nil
}

