// createMCPServer creates and configures the MCP server.
// [🧰composerepo⌨️mcp💻main🔖server🛠️createmcpserver](composerepo://p/i/repo/b/b/mcp/f/main.go/s/Server/d/i/createMCPServer)
func createMCPServer() *mcp.Server {
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "repo",
		Version: "1.0.0",
	}, nil)

	// Add search tool
	mcp.AddTool(server, &mcp.Tool{
		Name:        "search",
		Description: "Search the repository for files, folders, and other resources",
		InputSchema: mcp.ToolInputSchema{
			Type: "object",
			Properties: map[string]mcp.ToolInputProperty{
				"query": {
					Type:        "string",
					Description: "Search query string",
				},
			},
			Required: []string{"query"},
		},
	}, Search)

	// Add ticket management tools
	mcp.AddTool(server, &mcp.Tool{
		Name:        "ticket_open",
		Description: "Open a new ticket in the repository",
		InputSchema: mcp.ToolInputSchema{
			Type: "object",
			Properties: map[string]mcp.ToolInputProperty{
				"goal": {
					Type:        "string",
					Description: "Goal ID for the ticket",
				},
				"title": {
					Type:        "string",
					Description: "Ticket title",
				},
				"prompt": {
					Type:        "string",
					Description: "Ticket prompt/description",
				},
				"client": {
					Type:        "string",
					Description: "Client used for this ticket",
				},
				"llm": {
					Type:        "string",
					Description: "LLM used for this ticket",
				},
			},
			Required: []string{"goal", "title", "prompt", "client", "llm"},
		},
	}, OpenTicket)

	mcp.AddTool(server, &mcp.Tool{
		Name:        "ticket_close",
		Description: "Close an existing ticket in the repository",
		InputSchema: mcp.ToolInputSchema{
			Type: "object",
			Properties: map[string]mcp.ToolInputProperty{
				"ticket_id": {
					Type:        "string",
					Description: "ID of the ticket to close",
				},
				"summary": {
					Type:        "string",
					Description: "Summary of work completed",
				},
			},
			Required: []string{"ticket_id", "summary"},
		},
	}, CloseTicket)

	return server
}

